#!/bin/bash
# Regenerate the Flatpak Go-module vendoring files from the current go.mod/go.sum.
#
# Why this exists: the Flatpak build compiles the app from source inside the
# sandbox with `go build -mod=vendor`, using the vendored modules listed in
# go.mod.yml + modules.txt (generated by flatpak-go-mod, offline). Those two
# files are COMMITTED to the repo, so they go stale whenever go.mod changes.
# Nov 2026: excelize was added to go.mod (Mail Merge Phase 2) and nobody
# regenerated them, so the Flatpak step failed on v0.5.0, v0.5.1 and v0.5.2
# with "inconsistent vendoring" — and re-running the failed jobs could never
# fix it, because the inputs were stale.
#
# Run this after ANY change to go.mod/go.sum and commit the result:
#   ./build/flatpak/flathub/regen-vendor.sh
# A CI check (flatpak-vendor-check.yml) fails the build if the committed
# files are stale, so a bad manifest can no longer reach a release.
#
# NOTE: flatpak-go-mod moves vendor/modules.txt into the output directory
# with a rename, so the output directory MUST be on the same filesystem as
# this repo. Generating straight into build/flatpak/flathub satisfies that;
# do not point -out at /tmp.

set -e

cd "$(dirname "$0")/../../.."

if command -v flatpak-go-mod >/dev/null 2>&1; then
  TOOL="flatpak-go-mod"
else
  echo "flatpak-go-mod not found, installing..."
  go install github.com/dennwc/flatpak-go-mod@latest
  TOOL="$(go env GOPATH)/bin/flatpak-go-mod"
fi

"$TOOL" -out build/flatpak/flathub

# The tool vendors into ./vendor first; drop it afterwards.
rm -rf vendor

echo ""
git diff --stat -- build/flatpak/flathub/go.mod.yml build/flatpak/flathub/modules.txt || true
echo "Done. If the files changed, commit them:"
echo "  git add build/flatpak/flathub/go.mod.yml build/flatpak/flathub/modules.txt"
